return [
  { json: { id: 1, question: "What is your full name?", field_name: "patient_name" } },
  { json: { id: 2, question: "What is your phone number?", field_name: "phone" } },
  { json: { id: 3, question: "Which doctor would you like to see? (Dr. Mehta / Dr. Rao / Dr. Fernandes)", field_name: "doctor_name" } },
  { json: { id: 4, question: "What date would you like to book? (DD-MM-YYYY)", field_name: "appointment_date" } },
  { json: { id: 5, question: "What time works for you? (e.g. 10:00 AM)", field_name: "appointment_time" } },
  { json: { id: 6, question: "What's the reason for your visit?", field_name: "reason_for_visit" } }
];

const allItems = $input.all().map(item => item.json);
const session = allItems.find(item => item.session_id !== undefined);
const questions = allItems.filter(item => item.question !== undefined);
questions.sort((a, b) => a.id - b.id);

const chatData = $('When chat message received').first().json;
const userMessage = chatData.chatInput;
const safeUserMessage = (userMessage || "").replace(/'/g, "''");

if (session.completed) {
  return [{
    json: {
      session_id: session.session_id,
      branch: "already_completed",
      reply_text: "Your appointment is already booked! If you need to make changes, please call the clinic directly."
    }
  }];
}
if (session.is_new_session) {
  const firstQuestion = questions.find(q => q.id === 1);
  return [{
    json: {
      session_id: session.session_id,
      branch: "new_session",
      current_step: 0,
      reply_text: `Hi! Let's book your appointment. I'll ask you ${questions.length} quick questions.\n\n${firstQuestion.question}`
    }
  }];
}
const answeredQuestion = questions.find(q => q.id === session.current_step + 1);
const currentQuestionText = answeredQuestion.question;
const newStep = session.current_step + 1;
const isComplete = newStep >= questions.length;
const nextQuestion = isComplete ? null : questions.find(q => q.id === newStep + 1);

return [{
  json: {
    session_id: session.session_id,
    branch: isComplete ? "complete" : "continue",
    current_step: newStep,
    answered_field_name: answeredQuestion.field_name,
    answered_value: safeUserMessage,
    answered_question_text: currentQuestionText,
    previous_answers: session.answers,
    reply_text: isComplete
      ? "Thanks! Let me check a few things and confirm your booking..."
      : nextQuestion.question
  }
}];

