const sessionData = $('Save Final Answer').first().json;
const answers = sessionData.answers;
const historyResults = $input.all();

const hasHistory = Boolean(historyResults.length > 0 && historyResults[0].json.full_name);
const pastAppointments = hasHistory ? historyResults[0].json.total_past_appointments : 0;
const pastNoShows = hasHistory ? historyResults[0].json.total_no_shows : 0;
let calculatedRisk;
if (pastAppointments === 0) {
  calculatedRisk = "MODERATE";
} else {
  const noShowRatio = pastNoShows / pastAppointments;
  if (noShowRatio >= 0.4) {
    calculatedRisk = "HIGH";
  } else if (noShowRatio >= 0.15) {
    calculatedRisk = "MODERATE";
  } else {
    calculatedRisk = "LOW";
  }
}

return [{
  json: {
    calculated_risk_level: calculatedRisk,
    session_id: sessionData.session_id,
    patient_name: answers.patient_name,
    phone: answers.phone,
    doctor_name: answers.doctor_name,
    appointment_date: answers.appointment_date,
    appointment_time: answers.appointment_time,
    reason_for_visit: answers.reason_for_visit,
    is_returning_patient: hasHistory,
    total_past_appointments: pastAppointments,
    total_no_shows: pastNoShows

  }
}];

