=You are a clinic scheduling assistant. A risk classification system has already determined this patient's no-show risk level. Your job is only to write a one-sentence explanation for it.

Patient: {{ $json.patient_name }}
Past appointments: {{ $json.total_past_appointments }}
Past no-shows: {{ $json.total_no_shows }}
Risk level (already determined): {{ $json.calculated_risk_level }}

Write a brief, natural one-sentence explanation for why this risk level makes sense, referencing their actual numbers.

Respond with ONLY a JSON object, nothing else:
{"reasoning": "your one sentence explanation"}

parameters.jsCode:
const aiOutput = $input.first().json.output;
const contextData = $('Prepare Risk Context').first().json;

let parsed;
try {
  parsed = JSON.parse(aiOutput);
} catch (e) {
  const match = aiOutput.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { risk_level: "UNKNOWN", reasoning: "Could not parse AI response" };
}

const safeReasoning = (parsed.reasoning || "").replace(/'/g, "''");

return [{
  json: {
    ...contextData,
    risk_level: contextData.calculated_risk_level,
    risk_reasoning: safeReasoning
  }
}];

const data = $input.first().json;

if (data.branch !== "continue") {
  return [{ json: data }];
}

const userInput = data.answered_value || "";
const issues = [];

if (userInput.length > 200) {
  issues.push("Input too long (max 200 characters)");
}

const injectionPatterns = [
  /ignore (previous|all|the) instructions/i,
  /you are now/i,
  /system prompt/i,
  /forget (everything|your instructions)/i,
  /act as/i
];
if (injectionPatterns.some(function(p) { return p.test(userInput); })) {
  issues.push("Input contains suspicious instruction-like language");
}

if (data.answered_field_name === "phone") {
  const digitsOnly = userInput.replace(/\D/g, "");
  if (digitsOnly.length !== 10) {
    issues.push("Phone number must be exactly 10 digits");
  }
}

if (data.answered_field_name === "appointment_date") {
  const datePattern = /^\d{2}-\d{2}-\d{4}$/;
  if (!datePattern.test(userInput)) {
    issues.push("Date must be in DD-MM-YYYY format");
  } else {
    const parts = userInput.split("-");
    const enteredDate = new Date(parseInt(parts[2]), parseInt(parts[1]) - 1, parseInt(parts[0]));
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    if (enteredDate < today) {
      issues.push("Date must be today or a future date");
    }
  }
}

if (data.answered_field_name === "appointment_time") {
  const timePattern = /^(0?[1-9]|1[0-2]):[0-5][0-9]\s?(AM|PM)$/i;
  if (!timePattern.test(userInput.trim())) {
    issues.push("Time must be in format like 10:00 AM");
  }
}

if (data.answered_field_name === "patient_name") {
  const namePattern = /^[A-Za-z\s.'-]{2,50}$/;
  if (!namePattern.test(userInput.trim())) {
    issues.push("Name should only contain letters and spaces");
  }
}


if (issues.length > 0) {
  return [{
    json: Object.assign({}, data, {
      branch: "guardrail_failed",
reply_text: "Warning: I could not accept that answer: " + issues.join(", ") + ". " + data.answered_question_text
    })
  }];
}

return [{ json: data }];

