const aiOutput = $input.first().json.output;
const originalData = $('Guardrail Check').first().json;

let parsed;
try {
  parsed = JSON.parse(aiOutput);
} catch (e) {
  const match = aiOutput.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { on_topic: true, reason: "" };
}

if (parsed.on_topic === false) {
  return [{
    json: Object.assign({}, originalData, {
      branch: "guardrail_failed",
      reply_text: "Warning: That doesn't seem related to " + originalData.answered_field_name + ". " + originalData.answered_question_text
    })
  }];
}

return [{ json: originalData }];
